// Extracts the 'jobs' array from the search response and outputs each job as an individual n8n item
const searchResponse = $input.first().json;
const jobs = searchResponse.jobs || [];

return jobs.map(job => ({
  json: {
    job_url: job.job_url,
    title: job.title,
    company: job.company,
    job_id: job.job_id
  }
}));

