// 1. Captura o texto do nó anterior
let inputText = $input.first().json.text

try {
  // 2. Transforma os caracteres '\n' literais em quebras de linha reais do JSON
  let jsonString = inputText.replace(/\\n/g, '\n');

  // 3. Converte a string limpa diretamente em um objeto JSON nativo
  let parsedJson = JSON.parse(jsonString);

  // 4. Retorna o resultado para o n8n
  return [{ json: parsedJson }];

} catch (error) {
  // Caso o LLM falhe na estrutura, retorna o erro sem quebrar o fluxo
  return [{ 
    json: { 
      error: "Falha ao converter o texto do LLM em JSON",
      originalText: inputText
    } 
  }];
}
